// Worker entry: the Next.js site built by OpenNext, plus the free daily cron trigger.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- the file only exists after a build
// @ts-ignore -- generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string; WORKER_SELF_REFERENCE: Fetcher };

export default {
  fetch: handler.fetch,
  // Calls the site's own cron route with the shared secret (the route refuses anything else).
  async scheduled(_event: ScheduledController, env: Env, ctx: ExecutionContext) {
    if (!env.CRON_SECRET) return;
    ctx.waitUntil(
      env.WORKER_SELF_REFERENCE.fetch("https://alieni.internal/api/cron/daily", {
        headers: { authorization: `Bearer ${env.CRON_SECRET}` },
      }),
    );
  },
} satisfies ExportedHandler<Env>;

// Re-export the Durable Object classes OpenNext may generate (none are used on the free set-up).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- the file only exists after a build
// @ts-ignore -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
